import{_ as t,a0 as o,w as p,s as d,I as i,x as n,a1 as a,A as l,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何定製 SSH 來簡化遠程訪問 | LCTT x X-CMD","titleTemplate":false,"description":"如何定製 SSH 來簡化遠程訪問 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何定製 SSH 來簡化遠程訪問 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何定製 SSH 來簡化遠程訪問 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170202 How to Configure Custom SSH Connections to Simplify Remote Access","title":"如何定製 SSH 來簡化遠程訪問","tag":"201703","desc":""},"relativePath":"201703/20170202 How to Configure Custom SSH Connections to Simplify Remote Access.md","filePath":"[post].md"}'),r={name:"201703/20170202 How to Configure Custom SSH Connections to Simplify Remote Access.md"};function c(u,s,g,k,f,m){const e=o("Link");return p(),d("div",null,[s[25]||(s[25]=i("h1",{id:"如何定製-ssh-來簡化遠程訪問",tabindex:"-1"},[n("如何定製 SSH 來簡化遠程訪問 "),i("a",{class:"header-anchor",href:"#如何定製-ssh-來簡化遠程訪問","aria-label":"Permalink to “如何定製 SSH 來簡化遠程訪問”"},"​")],-1)),i("p",null,[s[1]||(s[1]=n("SSH （指 SSH 客户端）是一個用於訪問遠程主機的程序，它使得用户能夠 ",-1)),a(e,{href:"http://www.tecmint.com/execute-commands-on-multiple-linux-servers-using-pssh/"},{default:l(()=>[...s[0]||(s[0]=[n("在遠程主機上執行命令",-1)])]),_:1}),s[2]||(s[2]=n("。這是在登錄遠程主機中的最受推崇的方法之一，因為其設計目的就是在非安全網絡環境上為兩台非受信主機的通信提供安全加密。",-1))]),s[26]||(s[26]=i("p",null,"SSH 使用系統全局以及用户指定（用户自定義）的配置文件。在本文中，我們將介紹如何創建一個自定義的 ssh 配置文件，並且通過特定的選項來連接到遠程主機。",-1)),s[27]||(s[27]=i("h3",{id:"先決條件",tabindex:"-1"},[n("先決條件： "),i("a",{class:"header-anchor",href:"#先決條件","aria-label":"Permalink to “先決條件：”"},"​")],-1)),i("ol",null,[i("li",null,[s[4]||(s[4]=n("你必須 ",-1)),a(e,{href:"http://www.tecmint.com/install-openssh-server-in-linux/"},{default:l(()=>[...s[3]||(s[3]=[n("在你的桌面 Linux 上安裝好 OpenSSH 客户端",-1)])]),_:1}),s[5]||(s[5]=n("。",-1))]),s[6]||(s[6]=i("li",null,"瞭解通過 ssh 進行遠程連接的常用選項。",-1))]),s[28]||(s[28]=i("h3",{id:"ssh-客户端配置文件",tabindex:"-1"},[n("SSH 客户端配置文件 "),i("a",{class:"header-anchor",href:"#ssh-客户端配置文件","aria-label":"Permalink to “SSH 客户端配置文件”"},"​")],-1)),s[29]||(s[29]=i("p",null,"以下為 ssh 客户端配置文件：",-1)),s[30]||(s[30]=i("ol",null,[i("li",null,[i("code",null,"/etc/ssh/ssh_config"),n(" 為默認的配置文件，屬於系統全局配置文件，包含應用到所有用户的 ssh 客户端的設置。")]),i("li",null,[i("code",null,"~/.ssh/config"),n(" 或者 "),i("code",null,"$HOME/.ssh/config"),n(" 為用户指定/自定義配置文件，這個文件中的配置只對指定的用户有效，因此，它會覆蓋掉默認的系統全局配置文件中的設置。這也是我們要創建和使用的文件。")])],-1)),i("p",null,[s[8]||(s[8]=n("默認情況下，用户是通過在 ssh 中輸入密碼來獲取驗證的，你可以以一個簡單的步驟來 ",-1)),a(e,{href:"http://www.tecmint.com/ssh-passwordless-login-using-ssh-keygen-in-5-easy-steps/"},{default:l(()=>[...s[7]||(s[7]=[n("使用 Keygen 來設置 ssh 無密碼登錄",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),s[31]||(s[31]=h(`<p>注：如果你的系統上不存在 <code>~/.ssh</code> 目錄，那就手動創建它，並設置如下權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/.ssh</span></span>
<span class="line"><span>$ chmod 0700 ~/.ssh</span></span></code></pre></div><p>以上的 <code>chmod</code> 命令表明，只有目錄屬主對該目錄有讀取、寫入和執行權限，這也是 ssh 所要求的設置。</p><h3 id="如何創建用户指定的-ssh-配置文件" tabindex="-1">如何創建用户指定的 SSH 配置文件 <a class="header-anchor" href="#如何創建用户指定的-ssh-配置文件" aria-label="Permalink to “如何創建用户指定的 SSH 配置文件”">​</a></h3><p>該文件並不會被默認創建的，所以你需要使用具有讀取/寫入權限的用户來創建它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch ~/.ssh/config</span></span>
<span class="line"><span>$ chmod 0700 ~/.ssh/config</span></span></code></pre></div><p>上述文件包含由特定主機定義的各個部分，並且每個部分只應用到主機定義中相匹配的部分。</p><p><code>~/.ssh/config</code> 文件的常見格式如下，其中所有的空行和以 <code>‘#’</code> 開頭的行為註釋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host  host1</span></span>
<span class="line"><span>ssh_option1=value1</span></span>
<span class="line"><span>ssh_option2=value1 value2</span></span>
<span class="line"><span>ssh_option3=value1</span></span>
<span class="line"><span>Host  host2</span></span>
<span class="line"><span>ssh_option1=value1</span></span>
<span class="line"><span>ssh_option2=value1 value2</span></span>
<span class="line"><span>Host  *</span></span>
<span class="line"><span>ssh_option1=value1</span></span>
<span class="line"><span>ssh_option2=value1 value2</span></span></code></pre></div><p>如上格式詳解：</p><ol><li><code>Host host1</code> 為關於 host1 的頭部定義，主機相關的設置就從此處開始，直到下一個頭部定義 <code>Host host2</code> 出現，這樣形成一個完整的定義。</li><li>host1 和 host2 是在命令列中使用的主機別名，並非實際的遠程主機名。</li><li>其中，如 ssh_option1=value1、ssh_option2=value1 value2 等配置選項將應用到相匹配的主機，可以縮進以看起來更整齊些。</li><li>對於 ssh_option2=value1 value2 這樣的選項，ssh 執行時會按照順序優先使用 value1 的值。</li><li>頭部定義 <code>Host *</code> (其中 <code>*</code> 為匹配模式/通配符，匹配零個或多個字符) 會匹配零個或者多個主機。</li></ol><p>仍舊以上述的格式為例，ssh 也是也這樣的形式類讀取配置文件的。如果你執行 ssh 命令來訪問遠程主機 host1，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh host1</span></span></code></pre></div><p>以上 ssh 命令會進行一下動作：</p><ol><li>匹配配置文件中主機別名 host1，並使用頭部定義中的各個設置項。</li><li>繼續匹配下一個主機定義，然後發現命令列中提供的主機名沒有匹配的了，所以接下來的各個設置項會被略過。</li><li>最後執行到最後一個主機定義 <code>Host *</code>， 這會匹配所有的主機。這裏，會將接下來的所有設置選項應用到所有的主機連接中。但是它不會覆寫之前已經有主機定義的那些選項。</li><li>ssh host2 與此類似。</li></ol><h3 id="如何使用用户指定的-shh-配置文件" tabindex="-1">如何使用用户指定的 shh 配置文件 <a class="header-anchor" href="#如何使用用户指定的-shh-配置文件" aria-label="Permalink to “如何使用用户指定的 shh 配置文件”">​</a></h3><p>在你理解了 ssh 客户端配置文件的工作方式之後，你可以通過如下方式來創建它。記得使用你的服務器環境中對應的選項、值 (主機別名、端口號、用户名等)。</p><p>通過你最喜歡的編輯器來打開配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ~/.ssh/config</span></span></code></pre></div><p>並定義必要的部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host fedora25</span></span>
<span class="line"><span>HostName 192.168.56.15</span></span>
<span class="line"><span>Port 22</span></span>
<span class="line"><span>ForwardX11 no</span></span>
<span class="line"><span>Host centos7</span></span>
<span class="line"><span>HostName 192.168.56.10</span></span>
<span class="line"><span>Port 22</span></span>
<span class="line"><span>ForwardX11 no</span></span>
<span class="line"><span>Host ubuntu</span></span>
<span class="line"><span>HostName 192.168.56.5</span></span>
<span class="line"><span>Port 2222</span></span>
<span class="line"><span>ForwardX11 yes</span></span>
<span class="line"><span>Host *</span></span>
<span class="line"><span>User tecmint</span></span>
<span class="line"><span>IdentityFile ~/.ssh/id_rsa</span></span>
<span class="line"><span>Protocol 2</span></span>
<span class="line"><span>Compression yes</span></span>
<span class="line"><span>ServerAliveInterval 60</span></span>
<span class="line"><span>ServerAliveCountMax 20</span></span>
<span class="line"><span>LogLevel INFO</span></span></code></pre></div><p>以上 ssh 配置文件的詳細解釋：</p><ol><li><code>HostName</code> - 定義真正要登錄的主機名，此外，你也可以使用數字 IP 地址，不管是在命令列或是 HostName 定義中都允許使用其中任一種。</li><li><code>User</code> – 指定以哪一個用户來登錄。</li><li><code>Port</code> – 設置連接遠程主機的端口，默認是 22 端口。但必須是遠程主機的 sshd 配置文件中定義的端口號。</li><li><code>Protocol</code> – 這個選項定義了優先使用 ssh 支持的協議版本。常用的值為 ‘1’ 和 ‘2’，同時使用兩個協議版本則必須使用英文逗號隔開。</li><li><code>IdentityFile</code> – 指定一個用於讀取用户 DSA、Ed25519、ECDSA 等授權驗證信息的文件。</li><li><code>ForwardX11</code> – 定義 X11 連接是否自動重定向到安全通道和 DISPLAY 設置。有兩個可以設置的值，即 <code>yes</code> 或 <code>no</code>。</li><li><code>Compression</code> – 默認值為 <code>no</code>，如果設置為 <code>yes</code>，則在連接遠程主機過程中使用壓縮進行傳輸。</li><li><code>ServerAliveInterval</code> – 設置當沒有收到服務器響應 （或者數據)）時的超時時間，單位為秒，ssh 會通過加密信道發送信息，請求服務器響應。默認值為 <code>0</code>，這意味着 ssh 不會向服務器發送響應請求；如果定義了 BatchMode 選項，則默認是 300 秒。</li><li><code>ServerAliveCountMax</code> – 設置服務器在沒有接收到服務器的任何響應時，由服務器發送的活動信息數量。</li><li><code>LogLevel</code> – 定義 ssh 登錄信息的的日誌冗餘級別。允許的值為：<code>QUIET</code>、<code>FATAL</code>、<code>ERROR</code>、<code>INFO</code>、<code>VERBOSE</code>、<code>DEBUG</code>、<code>DEBUG1</code>、<code>DEBUG2</code> 和 <code>DEBUG3</code>，默認為 <code>INFO</code>。</li></ol><p>連接任意遠程主機的標準方法是在上述兩個文件中定義第二個部分（我連接的是 CentOS 7）。一般情況下，我們這樣輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -i ~/.ssh/id_rsa -p 22 tecmint@192.168.56.10</span></span></code></pre></div><p>然而，使用了 ssh 客户端配置文件之後，我們還可以這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh centos7</span></span></code></pre></div><p>你也可以在 man 幫助頁面尋找更多的設置選項和使用實例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$man ssh_config</span></span></code></pre></div><p>至此，文畢。我們在文中向你介紹了在 Linux 中如何使用用户指定 (自定義) 的 ssh 客户端配置文件。通過下方的反饋表單來寫一些與本文的相關的想法吧。</p><hr><p>作者簡介：</p><p>Aaron Kili 是一名 Linux 和 F.O.S.S 忠實擁護者、高級 Linux 系統管理員、Web 開發者，目前在 TecMint 是一名活躍的博主，熱衷於計算機並有着強烈的只是分享意願。</p><hr><p>譯者簡介：</p>`,35)),i("p",null,[a(e,{href:"http://GHLandy.com"},{default:l(()=>[...s[10]||(s[10]=[n("GHLandy",-1)])]),_:1}),s[11]||(s[11]=n(" —— 生活中所有歡樂與苦悶都應藏在心中，有些事兒註定無人知曉，自己也無從説起。",-1))]),s[32]||(s[32]=i("hr",null,null,-1)),i("p",null,[s[13]||(s[13]=n("via: ",-1)),a(e,{href:"http://www.tecmint.com/configure-custom-ssh-connection-in-linux/"},{default:l(()=>[...s[12]||(s[12]=[n("http://www.tecmint.com/configure-custom-ssh-connection-in-linux/",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("作者：",-1)),a(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:l(()=>[...s[14]||(s[14]=[n("Aaron Kili",-1)])]),_:1}),s[18]||(s[18]=n(" 譯者：",-1)),a(e,{href:"https://github.com/GHLandy"},{default:l(()=>[...s[15]||(s[15]=[n("GHLandy",-1)])]),_:1}),s[19]||(s[19]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[n("Linux中國",-1)])]),_:1}),s[24]||(s[24]=n(" 榮譽推出",-1))])])}const C=t(r,[["render",c]]);export{v as __pageData,C as default};
